<div class="page-head"><div><div class="breadcrumb"><a href="<?= e(url('/giving')) ?>"><?= e(__('Giving')) ?></a></div><h1><?= e(__('Giving statements')) ?></h1><p><?= e(__('Financial year 1 July %d – 30 June %d', $fy, $fy + 1)) ?></p></div>
<div class="actions"><form method="get" action="<?= e(base_path() . '/index.php') ?>" class="form-row"><input type="hidden" name="r" value="/giving/statements"><label><select name="fy" aria-label="<?= e(__('Financial year')) ?>"><?php for ($y = (int)date('Y'); $y >= (int)date('Y') - 6; $y--): ?><option value="<?= $y ?>" <?= $y === $fy ? 'selected' : '' ?>><?= $y ?>–<?= $y + 1 ?></option><?php endfor; ?></select></label><button class="btn"><?= e(__('Show')) ?></button></form>
<?php if (can('giving.manage') && $donors): ?><form method="post" action="<?= e(url('/giving/statements/email')) ?>" data-confirm="<?= e(__('Email a statement to every donor with an email address?')) ?>"><?= csrf_field() ?><input type="hidden" name="fy" value="<?= $fy ?>"><button class="btn btn-primary"><?= e(__('Email all statements')) ?></button></form><?php endif; ?></div></div>
<div class="card table-wrap"><table><thead><tr><th><?= e(__('Donor')) ?></th><th><?= e(__('Gifts')) ?></th><th><?= e(__('Total')) ?></th><th><span class="sr-only"><?= e(__('Actions')) ?></span></th></tr></thead><tbody>
<?php foreach ($donors as $d): ?><tr><td><?= e(person_name($d)) ?> <span class="small muted"><?= e($d['email']) ?></span></td><td><?= (int)$d['gifts'] ?></td><td><?= e(fmt_money((int)$d['total'])) ?></td><td><a class="btn btn-sm" href="<?= e(url('/giving/statement/' . $d['id'], ['fy' => $fy])) ?>" target="_blank"><?= e(__('View / print')) ?></a></td></tr><?php endforeach; ?>
<?php if (!$donors): ?><tr><td colspan="4" class="empty"><?= e(__('No gifts from known donors in this year.')) ?></td></tr><?php endif; ?></tbody></table></div>
